#ifndef FONT_H
#define FONT_H

/*
 * The x86 BASIC 8x8 character set (core/font.c, generated by
 * tools/mkfont.py): an original font, drawn for this project.
 * Characters 32-127, 8 bytes each (top row first, bit 7 = left); 96 is
 * the pound sign and 127 the copyright sign, as on the Spectrum.
 */
extern const unsigned char font[96][8];

#endif
